<?php
declare(strict_types=1);
// Private runtime synthetic crypto configuration is shared across QA processes only.
// The retained isolation MU plugin intercepts transport; no SMTP credential is used.
define('WP_CLI',true);
require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Learning\Subscriptions;
use AISkillsHub\Core\Accounts\{Crypto,Store};
$service=$core->get('learning_subscriptions');$worker=$core->get('account_mail_worker');$store=$core->get('account_store');
if (!defined('AISH_ACCOUNT_MAIL_KEY_VERSION') || AISH_ACCOUNT_MAIL_KEY_VERSION !== 'p14qa') { throw new RuntimeException('Install private Phase14 synthetic mail configuration first.'); }
$saved=$service->snapshot();wp_set_current_user($admin);$service->saveConfig(['enabled'=>true,'paused'=>false],$saved['revision']);
$prefs=fn(string $locale='en_US'):array=>['locale'=>$locale,'weekly'=>true,'new_resources'=>false,'consent'=>true];
$key=fn():string=>bin2hex(random_bytes(32));
$row=fn(int $id):?array=>$db->row('SELECT * FROM '.$db->table('notification_outbox').' WHERE id=%d',[$id]);
$latest=fn(int $id):?array=>$db->row('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_confirm' ORDER BY id DESC LIMIT 1",[$id]);
$unsub=fn(int $id):string=>Crypto::newsletterToken($id,$service->rawState($id)['generation'],$service->rawState($id)['nonce'],$service->rawState($id)['key_version'])['token'];
$age=function(int $id)use($service,$db):void{$s=$service->rawState($id);$s['requested_at']='2000-01-01 00:00:00';$db->execute('UPDATE '.$db->connection()->usermeta.' SET meta_value=%s WHERE user_id=%d AND meta_key=%s',[wp_json_encode($s),$id,$service->storageKey()]);wp_cache_delete($id,'user_meta');};
$start=function(string $suffix,string $locale='en_US',bool $confirm=true)use($service,$prefs,$key,$latest,$store):array{$id=p14_user($suffix);wp_set_current_user($id);$service->request($prefs($locale),$key());$mail=$latest($id);$token=$store->decryptPayload($mail)['token'];if($confirm)p14_assert($service->confirm($token)==='active','Synthetic opt-in confirms through production service');return ['id'=>$id,'token'=>$token,'mail_id'=>(int)$mail['id']];};
$force=function(int $id)use($db):void{$db->execute('UPDATE '.$db->table('notification_outbox')." SET available_at='1971-01-01 00:00:00' WHERE id=%d",[$id]);};
$accepted=true;$definite=false;$messages=[];
add_filter('pre_wp_mail',static function($value,$mail)use(&$accepted,&$messages){$messages[]=$mail;return $accepted;},PHP_INT_MAX,2);
add_filter('aish_account_mail_rejection_is_definite',static function()use(&$definite){return $definite;},PHP_INT_MAX);
try {
p14_case('verified_current_owner_explicit_consent_only_no_automatic_enrollment',function()use($service,$prefs,$key,$db){
 $unverified=p14_user('newsletter-pending-account',false);$member=p14_user('newsletter-explicit');foreach([$unverified,$member]as$id)p14_assert($service->rawState($id)===null,'Native registration/verification does not subscribe');
 wp_set_current_user(0);p14_reject(fn()=>$service->request($prefs(),$key()),'Guest cannot create newsletter identity');wp_set_current_user($unverified);p14_reject(fn()=>$service->request($prefs(),$key()),'Unverified account cannot subscribe');
 wp_set_current_user($member);foreach([['consent'=>false],['weekly'=>false],['locale'=>'fr_FR'],['user_id'=>$unverified],['email'=>'attacker@example.invalid']]as$patch)p14_reject(fn()=>$service->request(array_replace($prefs(),$patch),$key()),'Missing consent or injected owner/preferences rejected');p14_assert($service->rawState($member)===null,'Invalid request leaves no subscription');
});
p14_case('double_confirmation_hashed_token_replay_and_private_projection',function()use($service,$prefs,$key,$latest,$store,$db){
 $id=p14_user('newsletter-double');wp_set_current_user($id);$request=$key();$service->request($prefs(),$request);$first=$latest($id);$s=$service->rawState($id);$token=$store->decryptPayload($first)['token'];
 p14_assert($s['state']==='pending'&&$s['confirmed_at']==='','Explicit request alone is not active');$service->request($prefs(),$request);p14_assert($latest($id)['id']===$first['id'],'Exact retry uses one encrypted confirmation row');
 p14_reject(fn()=>$service->request(array_replace($prefs(),['locale'=>'zh_CN']),$request),'Same request identity cannot mutate payload');p14_reject(fn()=>$service->request($prefs(),$key()),'Fast resend is rate-limited');
 $v=$store->verification($token);p14_assert($v['purpose']==='newsletter'&&!str_contains(wp_json_encode($v),$token),'Existing verification table stores only token hash');p14_assert(!str_contains(wp_json_encode($s),$token)&&!str_contains($first['payload_ciphertext'],$token),'Raw confirmation is absent from consent and encrypted outbox bytes');
 $before=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type='user' AND subject_id=%d",[$id]);
 $other=p14_user('newsletter-confirm-other');foreach([0,$other]as$actor){wp_set_current_user($actor);$rejected=false;try{$rejected=$service->confirm($token)!=='active';}catch(Throwable $e){$reason=property_exists($e,'reason')?$e->reason:$e->getMessage();$rejected=in_array($reason,['login_required','verification_required','forbidden','invalid_token'],true);}p14_assert($rejected&&$service->rawState($id)['state']==='pending','Guest or other account cannot activate this owner consent');}
 wp_set_current_user($id);p14_assert($service->confirm($token)==='active'&&$service->confirm($token)==='active','Matching verified owner confirms once and safely acknowledges replay');p14_assert((int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type='user' AND subject_id=%d",[$id])===$before+1,'Confirmation replay creates no second business event');
 wp_set_current_user($id);$project=wp_json_encode($service->accountPreferences());foreach(['email_hash','nonce','unsubscribe_hash','key_version','verification_id',$token]as$private)p14_assert(!str_contains($project,$private),'Private subscription projection excludes credential metadata');
});
p14_case('expired_confirmation_does_not_activate_or_regenerate',function()use($start,$service,$store,$db){$f=$start('newsletter-expired','zh_CN',false);$state=$service->rawState($f['id']);$db->execute('UPDATE '.$db->table('email_verifications')." SET expires_at='2000-01-01 00:00:00' WHERE id=%d",[$state['verification_id']]);p14_assert($service->confirm($f['token'])==='expired'&&$service->rawState($f['id'])['state']==='pending','Expired confirmation stays inactive');p14_assert($service->tokenContext($f['token'],'confirm')===null,'Expired credential has no valid browser context');});
p14_case('bilingual_confirmation_transport_acceptance_is_mock_not_delivery',function()use($start,$service,$worker,$force,$row,&$messages,&$accepted){foreach(['zh_CN','en_US']as$locale){$f=$start('newsletter-template-'.$locale,$locale,false);$accepted=true;$before=count($messages);$force($f['mail_id']);$worker->run();$r=$row($f['mail_id']);p14_assert($r['status']==='accepted'&&$r['payload_ciphertext']===null,'Intercepted transport acceptance clears encrypted payload');p14_assert(count($messages)===$before+1,'One intercepted wp_mail call');$message=$messages[array_key_last($messages)];p14_assert(str_contains($message['subject'],$locale==='zh_CN'?'确认自愿邮件订阅':'Confirm your optional email subscription'),'Independent bilingual template');p14_assert($service->rawState($f['id'])['state']==='pending','Transport acceptance never confirms consent or claims delivery');}});
p14_case('unsubscribe_is_idempotent_cancels_pending_mail_and_never_changes_account',function()use($start,$service,$unsub,$row,$accounts,$db){$f=$start('newsletter-cancel');$token=$unsub($f['id']);$beforeState=$accounts->state($f['id']);wp_set_current_user(0);p14_assert($service->unsubscribe($token)&&$service->unsubscribe($token),'Bearer cancellation safe without login and repeatable');p14_assert($service->rawState($f['id'])['state']==='unsubscribed'&&$row($f['mail_id'])['status']==='cancelled','Pending newsletter mail cancelled');p14_assert($accounts->state($f['id'])===$beforeState&&$accounts->verified($f['id']),'Unsubscribe does not disable security/account verification');p14_assert(!$service->unsubscribe(str_repeat('0',64)),'Unknown token does not identify a subscriber');});
p14_case('new_consent_generation_invalidates_old_cancel_and_old_confirmation',function()use($start,$service,$unsub,$age,$prefs,$key,$latest,$store){$f=$start('newsletter-generation');$old=$unsub($f['id']);$service->unsubscribe($old);$age($f['id']);wp_set_current_user($f['id']);$service->request($prefs('zh_CN'),$key());$next=$latest($f['id']);$token=$store->decryptPayload($next)['token'];p14_assert($service->rawState($f['id'])['generation']===2&&$service->rawState($f['id'])['state']==='pending','Changed consent requires fresh pending generation');p14_assert(!$service->unsubscribe($old)&&$service->confirm($f['token'])==='invalid','Old generation credentials cannot cancel or activate current consent');p14_assert($service->confirm($token)==='active'&&$unsub($f['id'])!==$old,'New generation has distinct cancellation token');});
p14_case('native_metadata_guard_and_email_change_preserve_consent_boundary',function()use($start,$service,$admin,$db,$unsub){$f=$start('newsletter-guard');wp_set_current_user($f['id']);$before=$service->rawState($f['id']);update_user_meta($f['id'],$service->storageKey(),'{}');add_user_meta($f['id'],$service->storageKey(),'{}');p14_assert($service->rawState($f['id'])===$before,'Generic native usermeta APIs cannot forge newsletter state');wp_set_current_user($admin);$result=wp_update_user(['ID'=>$f['id'],'user_email'=>'changed-'.$f['id'].'@example.invalid']);p14_assert(!is_wp_error($result),'Native email update succeeds');wp_set_current_user($f['id']);p14_assert($service->accountPreferences()['state']!=='active','Email change invalidates old subscription eligibility');p14_assert($service->confirm($f['token'])==='invalid','Old address confirmation cannot restore eligibility');});
p14_case('manager_pause_bounce_projections_and_subscriber_permissions',function()use($start,$service,$admin){$f=$start('newsletter-bounce');wp_set_current_user($f['id']);foreach([fn()=>$service->listing(),fn()=>$service->detail($f['id']),fn()=>$service->mailFailures(),fn()=>$service->preview('en_US')]as$op)p14_reject($op,'Subscriber cannot use mail operations');wp_set_current_user($admin);$s=$service->detail($f['id']);p14_assert(str_starts_with($s['email'],'***@')&&!isset($s['nonce'],$s['email_hash']),'Admin listing minimizes address and credential exposure');$service->markBounce($f['id'],$s['revision'],'Synthetic manually reported permanent bounce');p14_assert($service->detail($f['id'])['state']==='bounced','Bounce stops active enrollment');p14_reject(fn()=>$service->setState($f['id'],$service->rawState($f['id'])['revision'],'active','Cannot opt another user in'),'Administrator cannot force active consent');});
p14_case('definite_transport_failure_retries_same_row_without_business_replay',function()use($start,$row,$force,$worker,$service,$db,&$accepted,&$definite){$f=$start('newsletter-retry','en_US',false);$before=$service->rawState($f['id']);$events=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type='user' AND subject_id=%d",[$f['id']]);$accepted=false;$definite=true;$force($f['mail_id']);$worker->run();p14_assert($row($f['mail_id'])['status']==='retry'&&(int)$row($f['mail_id'])['attempts']===1,'Definite Mock rejection schedules bounded retry');$accepted=true;$force($f['mail_id']);$worker->run();p14_assert($row($f['mail_id'])['status']==='accepted'&&(int)$row($f['mail_id'])['attempts']===2,'Retry accepts same existing outbox record');p14_assert($service->rawState($f['id'])===$before&&(int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type='user' AND subject_id=%d",[$f['id']])===$events,'Mail failure never replays consent business event');});
p14_case('ambiguous_transport_result_is_not_automatically_retried',function()use($start,$row,$force,$worker,&$accepted,&$definite){$f=$start('newsletter-uncertain','en_US',false);$accepted=false;$definite=false;$force($f['mail_id']);$worker->run();$r=$row($f['mail_id']);p14_assert($r['status']==='uncertain'&&$r['payload_ciphertext']===null,'Uncertain Mock transport result is terminal without plaintext payload');$accepted=true;});
p14_case('shared_outbox_retry_requires_both_queue_and_newsletter_capabilities',function()use($start,$row,$force,$worker,$core,$db,$admin,&$accepted,&$definite){
 $f=$start('newsletter-retry-cap','en_US',false);$accepted=false;$definite=true;$force($f['mail_id']);$worker->run();$accepted=true;$before=$row($f['mail_id']);p14_assert($before['status']==='retry','Actual rejected confirmation is retryable');
 $queueManager=p14_user('newsletter-queue-manager');$newsletterManager=p14_user('newsletter-only-manager');wp_set_current_user($admin);get_userdata($queueManager)->add_cap('aish_manage_notifications');get_userdata($newsletterManager)->add_cap('aish_manage_subscriptions');$mailOps=$core->get('operations_mail');
 $events=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type='mail_message' AND subject_id=%d",[$f['mail_id']]);wp_set_current_user($queueManager);$rows=$mailOps->listing('retry');$mine=p14_find($rows,$f['mail_id']);p14_assert($mine!==null&&!$mine['can_retry'],'Queue-only administrator sees no newsletter retry button');p14_reject(fn()=>$mailOps->retry($f['mail_id']),'Queue-only direct retry denied',['mail_forbidden']);
 wp_set_current_user($newsletterManager);p14_reject(fn()=>$mailOps->retry($f['mail_id']),'Newsletter-only role still needs shared queue capability',['mail_forbidden']);p14_assert($row($f['mail_id'])===$before&&(int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events')." WHERE subject_type='mail_message' AND subject_id=%d",[$f['mail_id']])===$events,'Denied retry changes no attempts, schedule or audit');
 wp_set_current_user($admin);get_userdata($queueManager)->add_cap('aish_manage_subscriptions');wp_set_current_user($queueManager);$mailOps->retry($f['mail_id']);$after=$row($f['mail_id']);p14_assert($after['available_at']<=$before['available_at']&&$after['attempts']===$before['attempts'],'Both capabilities can schedule known-unsent row without sending or resetting attempts');
});
p14_case('privacy_export_erasure_and_other_owner_isolation',function()use($start,$service,$admin,$unsub,$db){$a=$start('newsletter-export');$b=$start('newsletter-export-other');$other=$service->rawState($b['id']);$token=$unsub($a['id']);wp_set_current_user($admin);$export=$service->exportAccount(['data'=>[],'done'=>true],get_userdata($a['id']),1);$json=wp_json_encode($export);p14_assert(str_contains($json,'aish-newsletter-'.$a['id'])&&!str_contains($json,$token)&&!str_contains($json,'unsubscribe_hash'),'Export contains consent preferences without credential');$service->eraseAccount($a['id']);p14_assert($service->rawState($a['id'])===null&&!$service->unsubscribe($token),'Erasure removes state and cancellation lookup');p14_assert($service->rawState($b['id'])===$other,'Other subscriber unchanged');});
} finally {wp_set_current_user($admin);$service->saveConfig(array_intersect_key($saved,array_flip(['enabled','paused'])),$service->snapshot()['revision']);}
p14_report('Real WordPress/MySQL verified-user explicit consent, existing verification/outbox storage, encrypted credential handling and privacy; ALL mail transport responses are Mock, no real SMTP or delivery verification');
